{
  "identity": {
    "name": "Creations Unlimited (Creations Unlimited Machining Inc.)",
    "location": "175 Shannon Dr, Nampa, ID 83687, U.S.",
    "claims": [
      {
        "statement": "The company's legal name is Creations Unlimited Machining Inc., established by [redacted] in 1989.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": "Creations Unlimited Machining Inc. was established by [redacted] in 1989."
      },
      {
        "statement": "The company is located at 175 Shannon Dr, Nampa, ID, 83687, U.S.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": "Creations Unlimited, 175 Shannon Dr, Nampa, ID, 83687, U.S. [redacted] [redacted]"
      },
      {
        "statement": "The company operated in Morgan Hill, California for 32 years before relocating to an 18,000 square foot facility in Nampa, Idaho in Summer 2021.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/about",
        "quote": "32 Years of Business in California before relocating to Nampa Idaho Summer 2021"
      }
    ]
  },
  "industry": {
    "industry": "Precision CNC Machining and Manufacturing",
    "activities": [
      "5-axis CNC precision machining",
      "Quick-turn prototyping",
      "Mild / low-volume production machining (1 to 2,500 pieces)",
      "First article inspection (FAI) services",
      "Overflow CNC machining work for other shops"
    ],
    "claims": [
      {
        "statement": "Creations Unlimited is a precision CNC shop specializing in complex 5-axis CNC parts.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": "Creations Unlimited is a full service precision CNC shop that specializes in complex 5 axis CNC parts that most shops are afraid to mill."
      },
      {
        "statement": "The company provides machining services to the hi-tech, medical, space, and aerospace industries.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/about",
        "quote": "Creations Unlimited continues to provide high quality machining to the hi-tech and medical industries and now have added machining services to the space and aerospace"
      },
      {
        "statement": "The company offers 5-axis CNC machining, quick-turn prototyping, mild production (1 to 2,500 pieces), first article inspection, and overflow work.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/services",
        "quote": "Jobs that range from 1 piece all the way up to 2500 pieces. We currently specialize in micro machining and medical device size machining"
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.creationsultd.com/",
    "claims": [
      {
        "statement": "The company operates an 18,000 square foot temperature-controlled facility in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/about",
        "quote": "State of the Art 18,000 Sq Ft facility with full temperature control."
      },
      {
        "statement": "Standard turnaround for 5-axis CNC milling quotes is under 24 hours with 2-week standard part delivery.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/services",
        "quote": "Quotes are returned in under 24 hours, parts delivered in 2 weeks standard."
      },
      {
        "statement": "The shop operates multi-pallet automated 5-axis machining cells capable of 24/7 lights-out machining.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/facilities",
        "quote": "24/7 Lights Out Machining"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company's Certifications page lists ISO 9001:2015, AS9100D Certificate, and ITAR Registration.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/certifications",
        "quote": "ISO 9001:2015 and AS9100D Certificate ITAR Registration"
      }
    ],
    "limitations": "Specific state business registration numbers, contractor license numbers (not applicable to a machine shop), or certificate numbers/expiration dates are not printed in the page text."
  },
  "existingSoftware": [
    {
      "product": "ProShop ERP / QMS",
      "purpose": "Paperless shop management, ERP, and integrated Quality Management System (ISO/AS9100 management, inspection reporting, cert management, FAIR generation)",
      "evidence": {
        "statement": "The Key Advantages page states that the company runs a paperless shop and integrated QMS with ProShop, and links to proshoperp.com.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/key-advantages",
        "quote": "Paperless shop with Proshop Integrated QMS with ProShop"
      }
    },
    {
      "product": "Siemens NX CAD/CAM",
      "purpose": "CAD/CAM programming and full machine code simulation for 5-axis CNC machines",
      "evidence": {
        "statement": "The About page lists Siemens NX CAD/CAM with full machine code simulation for every 5-axis machine.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/about",
        "quote": "Siemens NX CAD/CAM with Full Machine Code Simulation for every 5 axis machines"
      }
    },
    {
      "product": "Calypso Software",
      "purpose": "Coordinate measuring machine (CMM) inspection software for Zeiss Contura G2",
      "evidence": {
        "statement": "The Facilities page lists Calypso Software under the Zeiss Contura G2 inspection equipment.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/facilities",
        "quote": "CALYPSO SOFTWARE"
      }
    },
    {
      "product": "Squarespace",
      "purpose": "Website content management and hosting",
      "evidence": {
        "statement": "The website loads scripts and assets from assets.squarespace.com, definitions.sqspcdn.com, and static1.squarespace.com.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": "https://assets.squarespace.com/@sqs/polyfiller/1.7.7/modern.js"
      }
    },
    {
      "product": "Adobe Typekit",
      "purpose": "Web font delivery",
      "evidence": {
        "statement": "The website loads font scripts from use.typekit.net.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": "use.typekit.net"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company already operates a paperless ERP with computer terminals at every machine and automated quality package/FAIR generation via ProShop.",
      "label": "fact",
      "sourceUrl": "https://www.creationsultd.com/about",
      "quote": "Paperless ERP with computer terminals at every machine"
    },
    {
      "statement": "The Contact / Request for Quote page displays an email address and phone number and references a Squarespace form visitor script, though no HTML form target was detected by the fetcher.",
      "label": "inference",
      "sourceUrl": "https://www.creationsultd.com/contact",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "No confirmed operational problems matching ForgeX's service catalog were identified; the company is a B2B CNC manufacturer with an existing paperless ERP/QMS (ProShop) rather than a residential home-service contractor.",
      "label": "inference",
      "basis": "Based on https://www.creationsultd.com/about and https://www.creationsultd.com/key-advantages, which show the business is a precision CNC machine shop already running ProShop ERP/QMS."
    }
  ],
  "existingSolutions": [
    {
      "solution": "ProShop ERP & QMS",
      "addresses": "Shop floor management, paperless documentation, real-time quality inspection monitoring, certification management, and First Article Inspection Report (FAIR) generation.",
      "alreadyOwned": true
    },
    {
      "solution": "Siemens NX CAD/CAM",
      "addresses": "5-axis CNC programming and full machine code simulation.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because Creations Unlimited is outside ForgeX's target segment of home-service contractors and already operates specialized manufacturing ERP/QMS software (ProShop)."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended for this business."
  },
  "humanReview": [],
  "risks": [
    {
      "type": "compliance",
      "description": "The company states it holds ITAR Registration and AS9100D certification for aerospace, space, and medical machining; any third-party cloud or AI automation handling technical drawings, quotes, or customer communications would face strict ITAR/export-control and quality compliance constraints."
    },
    {
      "type": "operational",
      "description": "ForgeX's core offerings are built around home-service field-service software, consumer lead intake, and QuickBooks reporting, which do not align with B2B aerospace/medical CNC machine shop workflows in ProShop ERP."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": []
  },
  "contacts": {
    "decisionMakerRoles": [
      "Founder / Owner",
      "President / General Manager"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Founder",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": "Creations Unlimited Machining Inc. was established by [redacted] in 1989."
      }
    ],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://www.creationsultd.com/"
      }
    ]
  },
  "discovery": {
    "questions": [],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.creationsultd.com/",
        "usedFor": "Company identity, Nampa ID address, contact details, founder [redacted], and principal 5-axis CNC machining focus."
      },
      {
        "url": "https://www.creationsultd.com/about",
        "usedFor": "Company history, relocation to 18,000 sq ft Nampa facility, industries served, Siemens NX CAD/CAM usage, and paperless ERP terminals."
      },
      {
        "url": "https://www.creationsultd.com/services",
        "usedFor": "Service offerings (5-axis machining, quick-turn prototyping, mild production, FAI, overflow work) and quote/delivery turnaround times."
      },
      {
        "url": "https://www.creationsultd.com/certifications",
        "usedFor": "ISO 9001:2015, AS9100D, and ITAR registration claims."
      },
      {
        "url": "https://www.creationsultd.com/contact",
        "usedFor": "Address and contact verification."
      },
      {
        "url": "https://www.creationsultd.com/key-advantages",
        "usedFor": "Verification of ProShop paperless ERP and integrated QMS usage and robotic pallet automation."
      },
      {
        "url": "https://www.creationsultd.com/facilities",
        "usedFor": "Verification of CNC equipment, 24/7 lights-out machining capability, and Calypso CMM software."
      },
      {
        "url": "https://www.creationsultd.com/quality",
        "usedFor": "Verification of CMM inspection capabilities and First Article Inspection services."
      }
    ],
    "limitations": [
      "Exact employee headcount is not stated on the public website.",
      "No service pricing is published on the website, as work is custom-quoted per project."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Creations Unlimited is a B2B 5-axis precision CNC machine shop serving aerospace, space, medical, and hi-tech manufacturing clients, placing it outside ForgeX's target segment of owner-led residential home-service contractors (HVAC, plumbing, and electrical). Furthermore, the company already operates a paperless shop floor and integrated QMS using ProShop ERP alongside robotic CNC automation."
  }
}
